values.content:
Assess onboarding health.

Customer: {{ $json.customerName }}
Days since signup: {{ $json.daysSinceSignup || 'unknown' }}
Expected onboarding duration: {{ $json.expectedOnboardingDays }} days
Team size: {{ $json.teamSize || 'unknown' }}
Active users: {{ $json.activeUsers || 'unknown' }}
Account value: {{ $json.accountValue ? $json.currency + $json.accountValue : 'unknown' }}
CSM: {{ $json.csmAssigned || 'unassigned' }}
Last contact: {{ $json.lastCustomerContact || 'not specified' }}
Notes: {{ $json.customerNotes || 'none' }}

Milestones:
{{ $json.onboardingMilestones.map(m=>m.name+' [expected day '+(m.expectedDay||'?')+'] ['+(m.criticalPath?'critical':'optional')+']: '+(m.completedDay!==null?'completed day '+m.completedDay:m.status)).join('\n') }}

Return JSON:
{"onboarding_health":"on_track|at_risk|stalled|completed","health_summary":"2-3 sentences on current state","completion_percent":0,"milestone_analysis":[{"milestone":"","status":"completed_on_time|completed_late|overdue|upcoming|not_started","days_variance":0,"is_blocking":false,"notes":""}],"blockers_identified":[{"blocker":"","likely_cause":"","suggested_action":""}],"churn_risk_from_onboarding":"high|medium|low|none","risk_rationale":"","recommended_next_action":{"action":"","urgency":"immediate|this_week|monitor","who_should_act":"csm|support|product|customer"},"projected_completion":"realistic estimate of when onboarding will complete given current pace, or 'on schedule' if on track"}
